import math

def is_good_triple(x, y, z):
    """Checks if (x, y, z) is a good triple."""
    if x <= 0 or y <= 0 or z <= 0:
        return False

    denominator = x**z + 1
    numerator = (x + 1)**y

    if denominator == 0:
        return False # Should not happen given positive integers

    return numerator % denominator == 0

# Test small values of x and z, and check y up to 10 for initial pattern recognition
X_values = [2, 3, 4]
Z_values = [1, 2, 3]
Y_limit = 10 # Checking up to y=10 for initial investigation

good_triples = {}

for x in X_values:
    good_triples[x] = {}
    for z in Z_values:
        found_for_xz = []
        for y in range(1, Y_limit + 1):
            if is_good_triple(x, y, z):
                found_for_xz.append(y)
        good_triples[x][z] = found_for_xz

print("--- Results ---")
for x, z_data in good_triples.items():
    print(f"x = {x}:")
    for z, y_list in z_data.items():
        print(f"  z = {z}: y values found: {y_list}")

def is_power_of_three(n):
    if n <= 0:
        return False
    while n % 3 == 0:
        n //= 3
    return n == 1

solutions = []
for z in range(1, 100):
    val = 2**z + 1
    if is_power_of_three(val):
        k = 0
        temp = val
        while temp > 1:
            temp //= 3
            k += 1
        solutions.append((z, k))

print("Solutions (z, k) for 2^z + 1 = 3^k where z < 100:")
print(solutions)

def check_powers_of_5(z):
    val = 4**z + 1
    if val <= 0:
        return None
    k = 0
    temp = val
    while temp > 0 and temp % 5 == 0:
        temp //= 5
        k += 1
    if temp == 1:
        return k
    return None

print("Checking 4^z + 1 = 5^k for z=2 to 10:")
for z in range(2, 11):
    k = check_powers_of_5(z)
    print(f"z={z}: 4^{z} + 1 = {4**z + 1}. Is power of 5? {k is not None}")
